def scheduleCourse(courses: list[list[int]]) -> int:
    import heapq
    courses.sort(key=lambda x: x[1])
    total_time = 0
    max_heap = []
    for dur, last_day in courses:
        if total_time + dur <= last_day:
            total_time += dur
            heapq.heappush(max_heap, -dur)
        elif max_heap and -max_heap[0] > dur:
            total_time += dur + heapq.heappop(max_heap)
            heapq.heappush(max_heap, -dur)
    return len(max_heap)

